using PiSignalWatch.Config; using PiSignalWatch.Models; using PiSignalWatch.Processing; using PiSignalWatch.Utilities;
public class ProcessingTests{[Fact] public async Task KeywordMatcherMatches(){var p=new KeywordMatcher(); var cfg=new AppSettings{Topics=[new(){Name="UFO",Keywords=["uap"]}]}; var r=await p.ProcessAsync([new(){Source=new(){Title="UAP report"}}],cfg,default); Assert.Single(r[0].TopicMatches);} [Fact] public async Task Deduplicates(){var d=new Deduplicator(); var cfg=new AppSettings(); var items=new List<ProcessedItem>{new(){Source=new(){Id="1",Url="u",Title="t",Content="c"}},new(){Source=new(){Id="1",Url="u",Title="t",Content="c"}}}; var r=await d.ProcessAsync(items,cfg,default); Assert.Single(r);} [Fact] public async Task Scores(){var s=new RelevanceScorer(new Fake()); var cfg=new AppSettings{Topics=[new(){Name="D",Keywords=["ai"]}]}; var it=new ProcessedItem{Source=new(){Title="defense ai",PublishedAt=DateTimeOffset.UtcNow.AddHours(-1)},TopicMatches=[new(){Topic="D",MatchedKeywords=["ai"]}]}; var r=await s.ProcessAsync([it],cfg,default); Assert.True(r[0].Score>0);} class Fake:IDateTimeProvider{public DateTimeOffset UtcNow=>DateTimeOffset.UtcNow;}}
